export function AltText({
  altText = "{{altText}}",
  decorative = {{decorative}},
  width = {{width}},
  showCaption = {{showCaption}},
}) {
  return (
    <div style={{ width: 340, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430" }}>
      <div style={{ minHeight: 90, border: "2px dashed #24143033", borderRadius: 10, background: "#FAF7F2", display: "grid", placeItems: "center", padding: 10, boxSizing: "content-box", width }}>
        <img src="does-not-exist.jpg" alt={decorative ? "" : altText} role={decorative ? "presentation" : undefined} style={{ display: "block", width }} />
      </div>
      {showCaption && <p style={{ marginTop: 10, fontSize: 12, fontFamily: "ui-monospace, monospace", color: "#241430aa", wordBreak: "break-word" }}>
        {decorative ? 'alt="" \u2014 image ignored by screen readers' : 'alt="' + altText + '"'}
      </p>}
    </div>
  );
}
